package com.avizero.avidrive.api;
import com.avizero.avidrive.domain.Setting; import com.avizero.avidrive.repository.*; import com.avizero.avidrive.security.AuthUser; import java.nio.file.*; import java.util.Map; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class AdminStatsController {private final UserRepository users;private final SettingRepository settings;public AdminStatsController(UserRepository u,SettingRepository s){users=u;settings=s;}
@GetMapping("/stats") public ResponseEntity<?> stats(Authentication a){if(!"ADMIN".equals(((AuthUser)a.getPrincipal()).role()))return ResponseEntity.status(403).body(Map.of("message","Недостаточно прав"));var all=users.findAll();long storage=all.stream().mapToLong(u->u.usedBytes==null?0:u.usedBytes).sum();long db=0;try{db=Files.size(Path.of("storage","avidrive.db"));}catch(Exception ignored){}Setting s=settings.findById(1L).orElseThrow();return ResponseEntity.ok(Map.of("users_total",users.count(),"users_active",all.stream().filter(u->!u.blocked).count(),"users_blocked",all.stream().filter(u->u.blocked).count(),"storage_bytes",storage,"db_size_bytes",db,"global_quota_mb",s.globalQuotaMb==null?0:s.globalQuotaMb,"global_used_bytes",storage));}}
